import{_ as e,o as a,c as o,ae as r}from"./chunks/framework.RRduUuAx.js";const m=JSON.parse('{"title":"WeChat Bill Import Guide","description":"","frontmatter":{},"headers":[],"relativePath":"v1/en/guide/02-wechat-bill-import-guide.md","filePath":"v1/en/guide/02-wechat-bill-import-guide.md"}'),i={name:"v1/en/guide/02-wechat-bill-import-guide.md"};function l(n,t,d,s,h,p){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="wechat-bill-import-guide" tabindex="-1">WeChat Bill Import Guide <a class="header-anchor" href="#wechat-bill-import-guide" aria-label="Permalink to &quot;WeChat Bill Import Guide&quot;">​</a></h1><h2 id="📋-overview" tabindex="-1">📋 Overview <a class="header-anchor" href="#📋-overview" aria-label="Permalink to &quot;📋 Overview&quot;">​</a></h2><p>This guide shows how to export bills from WeChat and import them into Koala.</p><hr><h2 id="📱-part-1-export-bills-in-wechat" tabindex="-1">📱 Part 1: Export bills in WeChat <a class="header-anchor" href="#📱-part-1-export-bills-in-wechat" aria-label="Permalink to &quot;📱 Part 1: Export bills in WeChat&quot;">​</a></h2><h3 id="step-1-open-the-bill-page" tabindex="-1">Step 1: Open the bill page <a class="header-anchor" href="#step-1-open-the-bill-page" aria-label="Permalink to &quot;Step 1: Open the bill page&quot;">​</a></h3><ol><li>Open WeChat</li><li>Tap <strong>Me</strong></li><li>Tap <strong>Services</strong> (or <strong>Pay</strong>)</li><li>Tap the <strong>Wallet</strong> icon (top-right)</li><li>Tap <strong>Bills</strong></li></ol><blockquote><p>📝 Note: The entry may differ across WeChat versions. If you can’t find it, try searching “账单”.</p></blockquote><h3 id="step-2-download-a-bill-file" tabindex="-1">Step 2: Download a bill file <a class="header-anchor" href="#step-2-download-a-bill-file" aria-label="Permalink to &quot;Step 2: Download a bill file&quot;">​</a></h3><ol><li>On the Bills page, tap <strong>...</strong> or <strong>Filter</strong>, then tap <strong>Download bills</strong> in the bottom sheet</li><li>Choose <strong>Personal reconciliation</strong></li><li>Choose delivery method (<strong>WeChat</strong> or <strong>Email</strong>)</li><li>Choose a date range and confirm</li></ol><blockquote><p>💡 Tips:</p><ul><li>Export up to 3 months at a time.</li><li>For longer history, export multiple files and import them one by one.</li></ul></blockquote><h3 id="step-3-save-the-file-to-your-device" tabindex="-1">Step 3: Save the file to your device <a class="header-anchor" href="#step-3-save-the-file-to-your-device" aria-label="Permalink to &quot;Step 3: Save the file to your device&quot;">​</a></h3><ul><li>If delivered via email: download the attachment and save it locally.</li><li>If saved to files: remember where you saved it.</li></ul><hr><h2 id="📱-part-2-import-into-koala" tabindex="-1">📱 Part 2: Import into Koala <a class="header-anchor" href="#📱-part-2-import-into-koala" aria-label="Permalink to &quot;📱 Part 2: Import into Koala&quot;">​</a></h2><h3 id="step-1-open-the-import-page" tabindex="-1">Step 1: Open the import page <a class="header-anchor" href="#step-1-open-the-import-page" aria-label="Permalink to &quot;Step 1: Open the import page&quot;">​</a></h3><ol><li>Open Koala</li><li>Tap <strong>Settings</strong></li><li>Find <strong>Bill Import</strong></li><li>Enter the bill import page</li></ol><h3 id="step-2-choose-the-import-source" tabindex="-1">Step 2: Choose the import source <a class="header-anchor" href="#step-2-choose-the-import-source" aria-label="Permalink to &quot;Step 2: Choose the import source&quot;">​</a></h3><ol><li>Tap <strong>Import source</strong></li><li>Select <strong>WeChat</strong></li></ol><blockquote><p>⚠️ Important: You must choose <strong>WeChat</strong>.</p></blockquote><h3 id="step-3-pick-the-file" tabindex="-1">Step 3: Pick the file <a class="header-anchor" href="#step-3-pick-the-file" aria-label="Permalink to &quot;Step 3: Pick the file&quot;">​</a></h3><ol><li>Tap <strong>File path</strong></li><li>Select the bill file exported from WeChat</li></ol><p>Supported formats:</p><ul><li><code>.csv</code></li><li><code>.xlsx</code> / <code>.xls</code></li></ul><h3 id="step-4-link-a-ledger" tabindex="-1">Step 4: Link a ledger <a class="header-anchor" href="#step-4-link-a-ledger" aria-label="Permalink to &quot;Step 4: Link a ledger&quot;">​</a></h3><ol><li>Tap <strong>Linked ledger</strong></li><li>Choose the target ledger</li></ol><h3 id="step-5-parse-preview-and-import" tabindex="-1">Step 5: Parse, preview, and import <a class="header-anchor" href="#step-5-parse-preview-and-import" aria-label="Permalink to &quot;Step 5: Parse, preview, and import&quot;">​</a></h3><ol><li>Tap <strong>Parse</strong> (top-right)</li><li>Review records on the preview page</li><li>Edit or delete invalid records if needed</li><li>Tap <strong>Import</strong></li></ol><hr><h2 id="📋-wechat-file-columns-for-reference" tabindex="-1">📋 WeChat file columns (for reference) <a class="header-anchor" href="#📋-wechat-file-columns-for-reference" aria-label="Permalink to &quot;📋 WeChat file columns (for reference)&quot;">​</a></h2><p>WeChat export typically contains columns like:</p><table tabindex="0"><thead><tr><th>Column name (as exported)</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td>交易时间</td><td>Transaction time</td><td>2024-01-01 12:00:00</td></tr><tr><td>交易类型</td><td>Transaction type</td><td>红包 / 转账 / 消费</td></tr><tr><td>交易对方</td><td>Counterparty</td><td>张三 / 商户</td></tr><tr><td>商品</td><td>Item description</td><td>午餐</td></tr><tr><td>收/支</td><td>Income/Expense</td><td>收入 / 支出</td></tr><tr><td>金额(元)</td><td>Amount</td><td>100.00</td></tr><tr><td>支付方式</td><td>Payment method</td><td>零钱 / 银行卡</td></tr><tr><td>当前状态</td><td>Status</td><td>支付成功</td></tr><tr><td>交易单号</td><td>Transaction ID</td><td>420000...</td></tr><tr><td>商户单号</td><td>Merchant ID</td><td>123...</td></tr><tr><td>备注</td><td>Note</td><td>...</td></tr></tbody></table><hr><h2 id="⚠️-notes" tabindex="-1">⚠️ Notes <a class="header-anchor" href="#⚠️-notes" aria-label="Permalink to &quot;⚠️ Notes&quot;">​</a></h2><ul><li>Don’t edit the exported WeChat file (especially headers/columns), otherwise parsing may fail.</li><li>Category matching may not be perfect; review and adjust in the preview page.</li></ul><hr><p><strong>Last updated</strong>: May 2026</p>',37)])])}const u=e(i,[["render",l]]);export{m as __pageData,u as default};
